package api.notice_p; import api.trash_p.TrashService; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import org.springframework.security.core.Authentication; import org.springframework.web.server.ResponseStatusException; import java.util.List; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class NoticeControllerTest { @Mock NoticeService service; @Mock TrashService trash; @Mock Authentication auth; @InjectMocks NoticeController controller;
 @Test @DisplayName("UT-BE-NOTICE-CTRL-001 알림 목록을 조회한다") void list(){ List<NoticeDTO>x=List.of(); when(service.list()).thenReturn(x); assertThat(controller.list()).isSameAs(x); } @Test @DisplayName("UT-BE-NOTICE-CTRL-002 알림 상세를 조회한다") void detail(){ NoticeDTO x=new NoticeDTO(); when(service.detail(1)).thenReturn(x); assertThat(controller.detail(1)).isSameAs(x); } @Test @DisplayName("UT-BE-NOTICE-CTRL-003 로그인 관리자가 알림 상태를 변경한다") void status(){ NoticeDTO d=new NoticeDTO(); when(auth.getName()).thenReturn("admin"); when(service.status("admin",d)).thenReturn(1); assertThat(controller.status(auth,7,d)).isEqualTo(1); assertThat(d.getNoticeNo()).isEqualTo(7); } @Test @DisplayName("UT-BE-NOTICE-CTRL-004 미인증 알림 상태 변경을 거부한다") void unauthorized(){ assertThatThrownBy(()->controller.status(null,1,new NoticeDTO())).isInstanceOf(ResponseStatusException.class); } @Test @DisplayName("UT-BE-NOTICE-CTRL-005 알림을 지난 기록으로 이동한다") void delete(){ assertThat(controller.delete(1)).isEqualTo(1); verify(trash).moveNotice(1,"MANUAL"); } @Test @DisplayName("UT-BE-NOTICE-CTRL-006 차량번호로 알림을 검색한다") void search(){ List<NoticeDTO>x=List.of(); when(service.search("3456")).thenReturn(x); assertThat(controller.search("3456")).isSameAs(x); } }
